# THE ONKELOS ROWS of Numbers 13:1-15:31 (THE NUMBERS WALK sitting 4 — SHELACH, 2026-09-10): verdict and prose per verse, the Aramaic
# and the Hebrew CUT by consonants (shelach_ink.H / shelach_ink.A — every miss collected, asserted empty by the writer). Every quotation
# SHORT and glossed at once (the lint's ninety-character window). 15:32-41 is frozen and skipped.
from shelach_ink import *
R = {}
def row(c, v, verdict, prose): R[(c, v)] = (verdict, prose)

# ---- 13:1-33 — the twelve sent; the seven questions; forty days; the cluster; the report and the evil report ----
row(13, 1, 'CONTEXT', 'The frame: "and the LORD spoke to Moses, saying" — the first of the portion\'s six (computed: 13:1, 14:11, 14:20, 14:26, 15:1, 15:17; two "said").')
row(13, 2, 'MATERIAL', f'SEND FOR YOURSELF. "{H(13, 2, "שלח", "לך", "אנשים")}" ("send for yourself men" — the Torah\'s one seat of the pair; computed) → {A(13, 2, "שלח", "לך", "גברין")} ("send for yourself men") — the reflexive kept (the exam\'s Sotah 34b: by your own will); "{H(13, 2, "ויתרו")}" ("and let them spy out") → {A(13, 2, "ויאללון")} ("and let them SCOUT" — the Aramaic scouting-verb, the translation\'s word at every seat of the spy-verb, twelve in the two chapters — computed); "{H(13, 2, "איש", "אחד", "איש", "אחד")}" ("one man, one man" — the parser reads 1, 1) → {A(13, 2, "גברא", "חד", "גברא", "חד")}; "{H(13, 2, "כל", "נשיא", "בהם")}" ("every one a prince among them") → {A(13, 2, "כל", "רבא", "דבהון")} ("every GREAT one among them"). The Sifrei has NO ROW on chapters 13-14 (computed on every head) — the story read on the translation alone.')
row(13, 3, 'MATERIAL', f'BY THE MOUTH OF THE LORD. "{H(13, 3, "על", "פי", "יהוה")}" ("by the mouth of the LORD") → {A(13, 3, "על", "מימרא", "דיי")} ("by the WORD of the LORD" — the Memra); "{H(13, 3, "ראשי", "בני", "ישראל", "המה")}" ("heads of the children of Israel were they") → {A(13, 3, "רישי", "בני", "ישראל", "אנון")} ("the heads of the children of Israel were they"). The register: "and he sent" (the store\'s gloss).')
row(13, 4, 'CONTEXT', f'THE LIST OPENS. "{H(13, 4, "ואלה", "שמותם")}" ("and these are their names") → {A(13, 4, "ואלין", "שמהתהון")}; Reuben first — the spies\' order is a FOURTH ORDER (computed): the census\' first four tribes, then Ephraim, Benjamin, Zebulun, Manasseh, Dan, Asher, Naphtali, Gad — neither the census list (1:5-15) nor the camp\'s (2, 7, 10).')
for v, who in [(5, 'Simeon'), (6, 'Judah — CALEB son of Jephunneh'), (7, 'Issachar'), (8, 'Ephraim — HOSHEA son of Nun (the name\'s one Numbers seat; computed)'), (9, 'Benjamin'), (10, 'Zebulun'), (12, 'Dan'), (13, 'Asher — Sethur, whose name carries the spy-verb\'s letters (computed: a homograph)'), (14, 'Naphtali'), (15, 'Gad, last')]:
    row(13, v, 'CONTEXT', f'The list: {who}. "{H(13, v, "למטה")}" ("for the tribe of") → {A(13, v, "לשבטא")} ("for the tribe of") — the translation\'s one word for the staff-word at all thirteen seats.')
row(13, 11, 'MATERIAL', f'JOSEPH\'S NAME OVER MANASSEH. "{H(13, 11, "למטה", "יוסף", "למטה", "מנשה")}" ("for the tribe of Joseph, for the tribe of Manasseh" — the pair\'s one seat; computed) → {A(13, 11, "לשבטא", "דיוסף", "לשבטא", "דמנשה")}: in the census Joseph\'s name stands over EPHRAIM ("of the sons of Joseph, of Ephraim" — 1:10, 1:32; computed), here over Manasseh — thirteen "for the tribe of" for twelve tribes (the exam\'s Sotah 36b reads the delta).')
row(13, 16, 'MATERIAL', f'HOSHEA RENAMED JOSHUA. "{H(13, 16, "ויקרא", "משה", "להושע", "בן", "נון", "יהושע")}" ("and Moses called Hoshea son of Nun Joshua") → {A(13, 16, "וקרא", "משה", "להושע", "בר", "נון", "יהושע")} — the translation keeps both names. THE INK: the NEW name already stands at eight seats before this verse (Exod 17:9-14, 24:13, 32:17, 33:11; Num 11:28 — computed), and the OLD name returns at the Torah\'s last song (Deut 32:44 "he and Hoshea son of Nun" — computed): the renaming verse sits inside a text that uses both. "{H(13, 16, "לתור", "את", "הארץ")}" ("to spy out the land") → {A(13, 16, "לאללא", "ית", "ארעא")} ("to scout the land").')
row(13, 17, 'MATERIAL', f'GO UP INTO THE SOUTH. "{H(13, 17, "עלו", "זה", "בנגב")}" ("go up this way in the south") → {A(13, 17, "סקו", "דא", "בדרומא")}; "{H(13, 17, "ועליתם", "את", "ההר")}" ("and go up into the mountain") → {A(13, 17, "ותסקון", "לטורא")} ("and go up to the mountain"). The register: "and he sent", "and he said" (the store\'s glosses).')
row(13, 18, 'MATERIAL', f'THE QUESTIONNAIRE OPENS. "{H(13, 18, "החזק", "הוא", "הרפה")}" ("is it strong or weak") → {A(13, 18, "התקיף", "הוא", "אם", "חלש")} ("is it MIGHTY, or weak" — the translation inserts "or" where the ink has two bare questions); "{H(13, 18, "המעט", "הוא", "אם", "רב")}" ("few or many") → {A(13, 18, "הזער", "הוא", "אם", "סגי")} ("is it few, or many"). THE INK\'S FORM (computed on the morphology): 13:18-20 carry four "what", SEVEN interrogative he\'s and five "or" — the seven questions the spies were sent with.')
row(13, 19, 'MATERIAL', f'OPEN CAMPS OR FORTRESSES. "{H(13, 19, "הטובה", "הוא", "אם", "רעה")}" ("is it good or bad") → {A(13, 19, "הטבא", "היא", "אם", "בישא")}; "{H(13, 19, "הבמחנים", "אם", "במבצרים")}" ("in camps or in fortresses") → {A(13, 19, "הבפצחין", "אם", "בכרכין")} ("in OPEN VILLAGES or in WALLED CITIES" — the translation\'s two technical words for the ink\'s "camps"/"fortresses", cut from the shelf\'s bytes).')
row(13, 20, 'MATERIAL', f'FAT OR LEAN; THE SEASON. "{H(13, 20, "השמנה", "הוא", "אם", "רזה")}" ("is it fat or lean") → {A(13, 20, "העתירא", "היא", "אם", "מסכנא")} ("is it RICH or POOR" — the soil\'s fatness rendered as wealth); "{H(13, 20, "היש", "בה", "עץ", "אם", "אין")}" ("is there a tree in it or not") → {A(13, 20, "האית", "בה", "אילנין", "אם", "לא")} ("are there TREES" — plural for the ink\'s singular); "{H(13, 20, "והימים", "ימי", "בכורי", "ענבים")}" ("and the days were the days of the first-ripe grapes" — the phrase\'s one seat; computed) → {A(13, 20, "ויומיא", "יומי", "בכורי", "ענבין")}: the season stamped in the ink — the shelf dates the sending to the twenty-ninth of Sivan (Taanit 29a:5, 3b\'s marker), the grapes\' first ripening.')
row(13, 21, 'MATERIAL', f'FROM ZIN TO THE ENTRANCE OF HAMATH. "{H(13, 21, "ממדבר", "צן", "עד", "רחב", "לבא", "חמת")}" ("from the wilderness of Zin to Rehob, to the entrance of Hamath") → {A(13, 21, "ממדברא", "דצין", "עד", "רחוב", "למטי", "חמת")} ("to Rehob, to the ARRIVAL at Hamath"); "the entrance of Hamath" in this spelling at two seats — here and the border chapter\'s 34:8 (computed): the spies walked the border the land-grant will draw; Zin at seven seats (computed). The register: "and they went up", "and they spied".')
row(13, 22, 'MATERIAL', f'HE CAME TO HEBRON; SEVEN YEARS BEFORE ZOAN. "{H(13, 22, "ויעלו", "בנגב", "ויבא", "עד", "חברון")}" ("and THEY went up in the south, and HE came to Hebron" — the number switch inside one verse, plural then singular, computed on the morphology: the exam\'s Sotah 34b reads Caleb alone at Hebron) → {A(13, 22, "וסליקו", "בדרומא", "ואתא", "עד", "חברון")} — the translation KEEPS the singular ("and he came"); "{H(13, 22, "אחימן", "ששי", "ותלמי", "ילידי", "הענק")}" ("Ahiman, Sheshai and Talmai, the children of the Anak" — the three named again at Josh 15:14 and Judg 1:10 when Caleb takes Hebron; computed) → {A(13, 22, "בני", "גבריא")} ("the sons of THE MIGHTY" — the Anak\'s children rendered as giants); "{H(13, 22, "שבע", "שנים", "נבנתה", "לפני", "צען", "מצרים")}" ("was built seven years before Zoan of Egypt" — the parser reads 7) → {A(13, 22, "שבע", "שנין", "אתבניאת", "קדם", "טנס", "דמצרים")} ("before TANIS of Egypt" — the Greek name for Zoan in the translation\'s bytes; Zoan at five seats, Psalm 78\'s "field of Zoan" among them — computed).')
row(13, 23, 'MATERIAL', f'THE CLUSTER ON A POLE BETWEEN TWO. "{H(13, 23, "נחל", "אשכל")}" ("the wadi of Eshcol" — spelled DEFECTIVE here, PLENE in the naming verse 13:24; computed) → {A(13, 23, "נחלא", "דאתכלא")}; "{H(13, 23, "זמורה", "ואשכול", "ענבים", "אחד")}" ("a branch and one cluster of grapes" — the branch-word\'s one seat) → {A(13, 23, "עוברתא", "ואתכל", "ענבין", "חד")}; "{H(13, 23, "וישאהו", "במוט", "בשנים")}" ("and they carried it on a pole, between two" — the parser reads 1, 2: THE DUAL WITH ITS PREFIX READ, 3b\'s rule at a fresh seat; the pole-word is the Kohathites\' carrying-bar word of 4:10, 4:12 — computed) → {A(13, 23, "ונטלוהי", "באריחא", "בתרין")} ("on a BAR, with TWO"); "{H(13, 23, "ומן", "הרמנים", "ומן", "התאנים")}" ("and of the pomegranates and of the figs") → {A(13, 23, "ומן", "רמוניא", "ומן", "תאניא")} ("and of the pomegranates and of the figs"). Eshcol the MAN stood at Hebron in Abram\'s day (Gen 14:13, 14:24 — the wadi\'s defective spelling is his; the Genesis seat by reference).')
row(13, 24, 'MATERIAL', f'THE NAMING. "{H(13, 24, "קרא", "נחל", "אשכול")}" ("he called the wadi Eshcol" — PLENE) → {A(13, 24, "קרא", "נחלא", "דאתכלא")}; "{H(13, 24, "על", "אדות", "האשכול")}" ("concerning the cluster" — "concerning" at seven seats, Miriam\'s 12:1 and this among them; Caleb\'s own "concerning me" at Josh 14:6 — computed) → {A(13, 24, "על", "עסק", "אתכלא")} ("on the MATTER of the cluster"). The name given by the event (E-rule: the place named by what happened there).')
row(13, 25, 'MATERIAL', f'FORTY DAYS. "{H(13, 25, "וישבו", "מתור", "הארץ", "מקץ", "ארבעים", "יום")}" ("and they returned from spying the land at the end of forty days" — the parser reads 40; "at the end of forty days" at three seats: Noah\'s window (Gen 8:6), the tablets (Deut 9:11), the spies — computed) → {A(13, 25, "ותבו", "מלאללא", "ית", "ארעא", "מסוף", "ארבעין", "יומין")} ("and they returned from scouting the land at the end of forty days"). THE TIMER for the compile: forty days from the sending (the shelf\'s twenty-ninth of Sivan) — the return on the shelf\'s ninth of Av (Taanit 29a:5, with its "Tammuz full" arm).')
row(13, 26, 'MATERIAL', f'TO KADESH; THEY BROUGHT BACK WORD. "{H(13, 26, "אל", "מדבר", "פארן", "קדשה")}" ("to the wilderness of Paran, to Kadesh" — the directional form\'s one Numbers seat, a homograph of the harlot-word and of Kedesh; the retellings say Kadesh-BARNEA — computed) → {A(13, 26, "למדברא", "דפארן", "לרקם")} ("to REKEM" — the translation\'s name for Kadesh, cut from the shelf\'s bytes); "{H(13, 26, "וישיבו", "אותם", "דבר")}" ("and they brought them back word" — one seat; Deut 1:22, 1:25 "brought us back word") → {A(13, 26, "ואתיבו", "יתהון", "פתגמא")}; "{H(13, 26, "ויראום")}" ("and they showed them" — one seat) → {A(13, 26, "ואחזיאנון")} ("and they showed them"). The register\'s densest verse: four narrative verbs (computed).')
row(13, 27, 'MATERIAL', f'FLOWING WITH MILK AND HONEY. "{H(13, 27, "וגם", "זבת", "חלב", "ודבש", "הוא")}" ("and also it flows with milk and honey" — the phrase\'s twenty seats, fifteen in the Torah; the spies say it of Canaan here and at 14:8, DATHAN OF EGYPT at 16:13 — computed) → {A(13, 27, "ואף", "עבדא", "חלב", "ודבש", "היא")} ("it MAKES milk and honey" — the flowing rendered as producing, the translation\'s standing form); "{H(13, 27, "וזה", "פריה")}" ("and this is its fruit") → {A(13, 27, "ודין", "אבה")} ("and this is its fruit").')
row(13, 28, 'MATERIAL', f'HOWEVER. "{H(13, 28, "אפס", "כי", "עז", "העם")}" ("however, the people is strong" — "however" at five seats; computed) → {A(13, 28, "לחוד", "ארי", "תקיף", "עמא")} ("ONLY, for mighty is the people"); "{H(13, 28, "בצרות", "גדלת", "מאד")}" ("fortified, very great" — Deuteronomy\'s retelling adds "to heaven", 1:28; computed) → {A(13, 28, "כריכן", "רברבן", "לחדא")} ("WALLED, very great"); "{H(13, 28, "ילדי", "הענק")}" ("the children of the Anak" — spelled DEFECTIVE here against 13:22\'s plene; computed) → {A(13, 28, "בני", "גבריא")} ("the sons of the mighty").')
row(13, 29, 'MATERIAL', f'THE MAP. "{H(13, 29, "עמלק", "יושב", "בארץ", "הנגב")}" ("Amalek dwells in the land of the south" — one seat) → {A(13, 29, "עמלקאה", "יתב", "בארע", "דרומא")}; the Hittite, Jebusite and Amorite in the MOUNTAIN, the Canaanite by the sea and the Jordan — a geography table by nation (the compile\'s data rows): at 14:25 the Amalekite and the Canaanite sit in the VALLEY, at 14:45 they come down from the MOUNTAIN (computed) — three seats, three placements; "{H(13, 29, "ועל", "יד", "הירדן")}" ("and by the side of the Jordan") → {A(13, 29, "ועל", "כיף", "ירדנא")} ("on the BANK of the Jordan").')
row(13, 30, 'MATERIAL', f'CALEB HUSHED THE PEOPLE. "{H(13, 30, "ויהס", "כלב", "את", "העם", "אל", "משה")}" ("and Caleb hushed the people toward Moses" — the hush-verb\'s one seat in the Bible; computed) → {A(13, 30, "ואצית", "כלב", "ית", "עמא", "למשה")} ("and Caleb made the people ATTEND to Moses" — the silencing rendered as making them listen); "{H(13, 30, "עלה", "נעלה")}" ("going up we will go up" — the doubled infinitive) → {A(13, 30, "מיסק", "ניסק")} (the doubling KEPT); "{H(13, 30, "יכול", "נוכל", "לה")}" ("being able we are able for it" — a second doubled infinitive, the two in one verse each at its one seat; computed) → {A(13, 30, "מיכל", "ניכול", "לה")} (kept again).')
row(13, 31, 'MATERIAL', f'STRONGER THAN WE — OR THAN HE. "{H(13, 31, "לא", "נוכל", "לעלות", "אל", "העם")}" ("we are not able to go up against the people") → {A(13, 31, "לא", "ניכול", "למיסק", "לות", "עמא")}; "{H(13, 31, "כי", "חזק", "הוא", "ממנו")}" ("for it is stronger than WE" — the suffix reads "than us" or "than Him": the store\'s gloss "from-us", the translation "than us" — computed and cut: {A(13, 31, "ארי", "תקיף", "הוא", "מננא")}; the exam\'s Sotah 35a reads "than He" — the blasphemy the translation does not carry).')
row(13, 32, 'MATERIAL', f'THE EVIL REPORT; A LAND THAT EATS ITS INHABITANTS. "{H(13, 32, "ויוציאו", "דבת", "הארץ")}" ("and they brought out the slander of the land" — the report-word at eight seats in the Bible, in the Torah only JOSEPH\'S (Gen 37:2 "their evil report") and the spies\' three; computed) → {A(13, 32, "ואפיקו", "שום", "ביש", "על", "ארעא")} ("and they brought out an EVIL NAME upon the land" — the slander as a bad name, the translation\'s idiom); "{H(13, 32, "ארץ", "אכלת", "יושביה", "הוא")}" ("a land that eats its inhabitants it is" — one seat; Ezekiel 36:13 "eater of men" the echo) → {A(13, 32, "ארעא", "מקטלת", "יתבהא", "היא")} ("a land that KILLS its inhabitants" — the metaphor resolved); "{H(13, 32, "אנשי", "מדות")}" ("men of measures" — one seat; Isaiah 45:14 "men of measure") → {A(13, 32, "אנשין", "דמשחן")} ("men of MEASURES"). The register: "and they brought out".')
row(13, 33, 'MATERIAL', f'THE NEPHILIM, PLENE AND DEFECTIVE; GRASSHOPPERS. "{H(13, 33, "הנפילים", "בני", "ענק", "מן", "הנפלים")}" ("the Nephilim, the sons of Anak, of the Nephilim" — spelled PLENE then DEFECTIVE in one verse, Genesis 6:4\'s defective; computed) → {A(13, 33, "גבריא", "בני", "ענק", "מן", "גבריא")} ("the MIGHTY, the sons of Anak, of the mighty" — one Aramaic word for the Nephilim and for the Anak\'s children at 13:22, 13:28: the translation\'s homograph across the chapter); "{H(13, 33, "ונהי", "בעינינו", "כחגבים")}" ("and we were in our own eyes as grasshoppers" — with Isaiah 40:22; computed) → {A(13, 33, "והוינא", "בעיני", "נפשנא", "כקמצין")} ("in the eyes of OURSELVES as LOCUSTS"); "{H(13, 33, "וכן", "היינו", "בעיניהם")}" ("and so we were in their eyes") → {A(13, 33, "וכן", "הוינא", "בעיניהון")} ("and so we were in their eyes").')
# ---- 14:1-45 — the night of weeping; the stoning and the glory; the plea on the attributes; a day for a year; the plague; Hormah ----
row(14, 1, 'MATERIAL', f'THAT NIGHT. "{H(14, 1, "ותשא", "כל", "העדה", "ויתנו", "את", "קולם")}" ("and all the congregation LIFTED — and THEY gave their voice" — the verb singular before "the congregation", then plural; computed on the morphology) → {A(14, 1, "וארימת", "כל", "כנשתא", "ויהבו", "ית", "קלהון")} (the translation keeps the switch); "{H(14, 1, "ויבכו", "העם", "בלילה", "ההוא")}" ("and the people wept THAT NIGHT" — "the people wept" one seat) → {A(14, 1, "ובכו", "עמא", "בליליא", "ההוא")} ("and the people wept on that night"). THE SHELF DATES THE NIGHT: the ninth of Av (Taanit 29a:5 — "you wept for nothing; I will fix for you a weeping for generations") — the tape\'s next reading-placed marker, forty days after 12:16\'s twenty-ninth of Sivan.')
row(14, 2, 'MATERIAL', f'WOULD WE HAD DIED. "{H(14, 2, "וילנו", "על", "משה", "ועל", "אהרן")}" ("and they murmured against Moses and against Aaron" — the murmur-root at twelve seats from Marah to Korach, five in this chapter; computed) → {A(14, 2, "ואתרעמו", "על", "משה", "ועל", "אהרן")}; "{H(14, 2, "לו", "מתנו", "בארץ", "מצרים")}" ("would we had died in the land of Egypt" — the wish TWICE in the verse, the pair\'s one seat; the manna\'s "would that we had died" (Exod 16:3) and Meribah\'s "would we had perished" (20:3) the other death-wishes — computed) → {A(14, 2, "לוי", "דמיתנא", "בארעא", "דמצרים")}; "{H(14, 2, "במדבר", "הזה", "לו", "מתנו")}" ("in THIS wilderness would we had died") → {A(14, 2, "במדברא", "הדין", "לוי", "דמיתנא")}: "in this wilderness" — the people\'s phrase, returned to them at 14:29, 14:32, 14:35 (the four seats all in this chapter; computed).')
row(14, 3, 'MATERIAL', f'OUR WIVES AND LITTLE ONES A PREY. "{H(14, 3, "נשינו", "וטפנו", "יהיו", "לבז")}" ("our wives and our little ones will be a prey") → {A(14, 3, "נשנא", "וטפלנא", "יהון", "לבזא")}; "{H(14, 3, "הלוא", "טוב", "לנו", "שוב", "מצרימה")}" ("is it not better for us to return to Egypt") → {A(14, 3, "הלא", "טב", "לנא", "די", "נתוב", "למצרים")} ("is it not better for us that we return to Egypt"). The little ones\' clause returned at 14:31 and verbatim at Deut 1:39 (computed).')
